diagram='''<figure><svg viewBox="0 0 900 280" role="img" aria-labelledby="s-title s-desc" xmlns="http://www.w3.org/2000/svg"><title id="s-title">Two handles, one receiver</title><desc id="s-desc">Lambda and phi controls point toward a reactor whose response must be checked.</desc><rect width="900" height="280" rx="18" fill="#121827"/><circle cx="690" cy="145" r="70" fill="#6c4e9e" stroke="#f0d48c" stroke-width="6"/><circle cx="690" cy="145" r="30" fill="#d887b7"/><path d="M180 95L620 135M180 205L620 155" stroke="#8fc7d5" stroke-width="8"/><circle cx="180" cy="95" r="28" fill="#85c89a"/><circle cx="180" cy="205" r="28" fill="#e9b86f"/><g font-family="system-ui,sans-serif" text-anchor="middle" fill="#f5f0ff"><text x="180" y="100" font-size="18">λ</text><text x="180" y="211" font-size="18">φ</text><text x="690" y="150" font-size="18">receiver</text><text x="450" y="42" font-size="22">a moving handle is not yet a causal connection</text><text x="450" y="260" font-size="17">show the input beside the response before naming the effect</text></g></svg><figcaption>The sandbox makes the missing link visible: controls need a receiver and an observable response.</figcaption></figure>'''
